def analyze_cfg(config, cfg):
    """Compute liveness, interference, and call-forbidden facts for a CFG.

    Returns a dict with live_in, live_out, interference, and call_forbidden in
    the public formats described by SPEC.md.
    """
    blocks = cfg["blocks"]
    block_by_id = {b["id"]: b for b in blocks}
    block_ids = [b["id"] for b in blocks]

    # Predecessor map.
    preds = {bid: [] for bid in block_ids}
    for b in blocks:
        for s in b["successors"]:
            preds[s].append(b["id"])

    # Per-block derived sets.
    phi_defs = {}
    use = {}
    defined = {}
    for b in blocks:
        bid = b["id"]
        phi_defs[bid] = set(p["def"] for p in b["phis"])
        u = set()
        d = set(phi_defs[bid])
        for ins in b["instructions"]:
            for v in ins["uses"]:
                if v not in d:
                    u.add(v)
            if ins["def"] is not None:
                d.add(ins["def"])
        use[bid] = u
        defined[bid] = d

    # Edge phi uses: edge_use(B, S) = successor S's phi inputs selected by B.
    edge_use = {}
    for b in blocks:
        bid = b["id"]
        for s in b["successors"]:
            sb = block_by_id[s]
            eu = set()
            for p in sb["phis"]:
                if bid in p["inputs"]:
                    eu.add(p["inputs"][bid])
            edge_use[(bid, s)] = eu

    # Least fixed point liveness.
    live_in = {bid: set() for bid in block_ids}
    live_out = {bid: set() for bid in block_ids}
    changed = True
    while changed:
        changed = False
        for b in blocks:
            bid = b["id"]
            new_out = set()
            for s in b["successors"]:
                new_out |= (live_in[s] - phi_defs[s]) | edge_use[(bid, s)]
            new_in = use[bid] | (new_out - defined[bid])
            if new_out != live_out[bid] or new_in != live_in[bid]:
                live_out[bid] = new_out
                live_in[bid] = new_in
                changed = True

    # Conservative undirected interference.
    interference = set()
    call_forbidden = {}  # variable -> set of registers

    def add_pairs(s):
        lst = sorted(s)
        for i in range(len(lst)):
            for j in range(i + 1, len(lst)):
                interference.add((lst[i], lst[j]))

    for b in blocks:
        bid = b["id"]
        live = set(live_out[bid])
        add_pairs(live)
        for ins in reversed(b["instructions"]):
            if ins["call"]:
                # Forbid every call_clobbered register for every variable in
                # live_after EXCEPT this instruction's own definition.
                for v in live:
                    if v == ins["def"]:
                        continue
                    cf = call_forbidden.setdefault(v, set())
                    cf.update(config["call_clobbered"])
            d = ins["def"]
            if d is not None:
                for v in live:
                    if v != d:
                        interference.add(tuple(sorted((d, v))))
                live.discard(d)
            for v in ins["uses"]:
                live.add(v)
            add_pairs(live)
        add_pairs(live)
        add_pairs(live_in[bid])

    # Convert to public formats.
    live_in_out = {bid: sorted(live_in[bid]) for bid in block_ids}
    live_out_out = {bid: sorted(live_out[bid]) for bid in block_ids}
    interference_out = [list(e) for e in sorted(interference)]
    call_forbidden_out = {
        v: sorted(regs) for v, regs in sorted(call_forbidden.items()) if regs
    }

    return {
        "live_in": live_in_out,
        "live_out": live_out_out,
        "interference": interference_out,
        "call_forbidden": call_forbidden_out,
    }

import unittest
import sys
import os

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "..", ".."))

from engines.analysis.cfg_facts import analyze_cfg


class TestCfgFacts(unittest.TestCase):
    def test_local_check_fixture(self):
        # P with parameter a, one call defining c, successor Q.
        # Q defines phi x from a on edge P->Q and has instruction using x and c.
        config = {"registers": ["R0"], "call_clobbered": ["R0"], "precolors": {}}
        cfg = {
            "entry": "P",
            "parameters": ["a"],
            "blocks": [
                {
                    "id": "P",
                    "successors": ["Q"],
                    "phis": [],
                    "instructions": [
                        {"id": "call", "uses": ["a"], "def": "c", "call": True}
                    ],
                },
                {
                    "id": "Q",
                    "successors": [],
                    "phis": [{"def": "x", "inputs": {"P": "a"}}],
                    "instructions": [
                        {"id": "use", "uses": ["x", "c"], "def": None, "call": False}
                    ],
                },
            ],
        }
        facts = analyze_cfg(config, cfg)
        self.assertEqual(set(facts["live_out"]["P"]), {"a", "c"})
        self.assertEqual(set(facts["live_in"]["Q"]), {"c"})
        self.assertEqual(set(map(tuple, facts["interference"])), {("a", "c"), ("c", "x")})
        self.assertEqual(facts["call_forbidden"], {"a": ["R0"]})

    def test_public_example(self):
        config = {"registers": ["R0", "R1"], "call_clobbered": [], "precolors": {"a": "R0", "b": "R1"}}
        cfg = {
            "entry": "E",
            "parameters": ["a", "b"],
            "blocks": [
                {"id": "E", "successors": ["P", "Q"], "phis": [], "instructions": []},
                {"id": "P", "successors": ["M"], "phis": [], "instructions": []},
                {"id": "Q", "successors": ["M"], "phis": [], "instructions": []},
                {
                    "id": "M",
