{"engines/analysis/cfg_facts.py": "def analyze_cfg(config, cfg):
    """Compute liveness, interference, and call-forbidden facts for a CFG.

    Returns a dict with live_in, live_out, interference, and call_forbidden in
    the public formats described by SPEC.md.
    """
    blocks = cfg["blocks"]
    block_by_id = {b["id"]: b for b in blocks}
    block_ids = [b["id"] for b in blocks]

    # Predecessor map.
    preds = {bid: [] for bid in block_ids}
    for b in blocks:
        for s in b["successors"]:
            preds[s].append(b["id"])

    # Per-block derived sets.
    phi_defs = {}
    use = {}
    defined = {}
    for b in blocks:
        bid = b["id"]
        phi_defs[bid] = set(p["def"] for p in b["phis"])
        u = set()
        d = set(phi_defs[bid])
        for ins in b["instructions"]:
            for v in ins["uses"]:
                if v not in d:
                    u.add(v)
            if ins["def"] is not None:
                d.add(ins["def"])
        use[bid] = u
        defined[bid] = d

    # Edge phi uses: edge_use(B, S) = successor S's phi inputs selected by B.
    edge_use = {}
    for b in blocks:
        bid = b["id"]
        for s in b["successors"]:
            sb = block_by_id[s]
            eu = set()
            for p in sb["phis"]:
                if bid in p["inputs"]:
                    eu.add(p["inputs"][bid])
            edge_use[(bid, s)] = eu

    # Least fixed point liveness.
    live_in = {bid: set() for bid in block_ids}
    live_out = {bid: set() for bid in block_ids}
    changed = True
    while changed:
        changed = False
        for b in blocks:
            bid = b["id"]
            new_out = set()
            for s in b["successors"]:
                new_out |= (live_in[s] - phi_defs[s]) | edge_use[(bid, s)]
            new_in = use[bid] | (new_out - defined[bid])
            if new_out != live_out[bid] or new_in != live_in[bid]:
                live_out[bid] = new_out
                live_in[bid] = new_in
                changed = True

    # Conservative undirected interference.
    interference = set()
    call_forbidden = {}  # variable -> set of registers

    def add_pairs(s):
        lst = sorted(s)
        for i in range(len(lst)):
            for j in range(i + 1, len(lst)):
                interference.add((lst[i], lst[j]))

    for b in blocks:
        bid = b["id"]
        live = set(live_out[bid])
        add_pairs(live)
        for ins in reversed(b["instructions"]):
            if ins["call"]:
                # Forbid every call_clobbered register for every variable in
                # live_after EXCEPT this instruction's own definition.
                for v in live:
                    if v == ins["def"]:
                        continue
                    cf = call_forbidden.setdefault(v, set())
                    cf.update(config["call_clobbered"])
            d = ins["def"]
            if d is not None:
                for v in live:
                    if v != d:
                        interference.add(tuple(sorted((d, v))))
                live.discard(d)
            for v in ins["uses"]:
                live.add(v)
            add_pairs(live)
        add_pairs(live)
        add_pairs(live_in[bid])

    # Convert to public formats.
    live_in_out = {bid: sorted(live_in[bid]) for bid in block_ids}
    live_out_out = {bid: sorted(live_out[bid]) for bid in block_ids}
    interference_out = [list(e) for e in sorted(interference)]
    call_forbidden_out = {
        v: sorted(regs) for v, regs in sorted(call_forbidden.items()) if regs
    }

    return {
        "live_in": live_in_out,
        "live_out": live_out_out,
        "interference": interference_out,
        "call_forbidden": call_forbidden_out,
    }
"}

{"engines/analysis/weighted_allocation.py": """"Weighted minimum-cost register allocation with frequency-weighted phi copies.

Implements the allocation half of SPEC.md: choose, for every variable, a
register or a spill slot so that:

  * pinned variables never spill and honor their precolor,
  * interfering register-resident variables never share a register,
  * no variable uses a call-forbidden register,
  * the total spill cost is minimized EXACTLY (primary objective),
  * among minimum-spill allocations, the frequency-weighted phi copy cost is
    minimized EXACTLY (secondary objective).

The search is exact: it enumerates every legal assignment of the (at most 22)
variables to registers/spill and keeps the best by (spill_cost, copy_cost).
"""


def _interference_graph(facts):
    """Return {var: set(neighbors)} from the facts interference edge list."""
    graph = {}
    for u, v in facts.get("interference", []):
        graph.setdefault(u, set()).add(v)
        graph.setdefault(v, set()).add(u)
    return graph


def _variables(cfg, spill_cost):
    """Return the ordered list of all variables (parameters + defs)."""
    seen = []
    for p in cfg.get("parameters", []):
        if p not in seen:
            seen.append(p)
    for block in cfg.get("blocks", []):
        for phi in block.get("phis", []):
            d = phi.get("def")
            if d is not None and d not in seen:
                seen.append(d)
        for ins in block.get("instructions", []):
            d = ins.get("def")
            if d is not None and d not in seen:
                seen.append(d)
    for v in spill_cost:
        if v not in seen:
            seen.append(v)
    return seen


def _precolor_errors(config, facts):
    """Return (status, reason) for precolor/call-clobber violations, else None."""
    precolors = config.get("precolors", {})
    call_forbidden = facts.get("call_forbidden", {})

    for var, reg in precolors.items():
        if var in call_forbidden and reg in call_forbidden[var]:
            return "UNSAT_PRECOLOR", "PRECOLOR_CALL_CLOBBER"

    graph = _interference_graph(facts)
    pinned = list(precolors.items())
    for i in range(len(pinned)):
        v1, r1 = pinned[i]
        for j in range(i + 1, len(pinned)):
            v2, r2 = pinned[j]
            if r1 == r2 and v2 in graph.get(v1, set()):
                return "UNSAT_PRECOLOR", "PRECOLOR_INTERFERENCE"

    return None


def _block_by_id(cfg, block_id):
    for block in cfg.get("blocks", []):
        if block["id"] == block_id:
            return block
    return None


def _copy_cost(cfg, edge_frequency, locations):
    """Compute frequency-weighted phi copy cost for a full location map."""
    freq = {}
    for row in edge_frequency:
        freq[(row["pred"], row["succ"])] = row["frequency"]

    total = 0
    for block in cfg.get("blocks", []):
        pred = block["id"]
        for succ in block.get("successors", []):
            f = freq.get((pred, succ), 0)
            succ_block = _block_by_id(cfg, succ)
            if succ_block is None:
                continue
            for phi in succ_block.get("phis", []):
                src = phi["inputs"].get(pred)
                if src is None:
                    continue
                dst = phi["def"]
                if locations[src] != locations[dst]:
                    total += f
    return total


def _has_cycle(moves):
    """True iff the distinct from->to transition graph has a directed cycle."""
    edges = set()
    for m in moves:
