import unittest

from engines.analysis.engine import transform


def _public_request():
    return {
        "config": {
            "registers": ["R0", "R1"],
            "call_clobbered": [],
            "precolors": {"a": "R0", "b": "R1"},
        },
        "cfg": {
            "entry": "E",
            "parameters": ["a", "b"],
            "blocks": [
                {"id": "E", "successors": ["P", "Q"], "phis": [], "instructions": []},
                {"id": "P", "successors": ["M"], "phis": [], "instructions": []},
                {"id": "Q", "successors": ["M"], "phis": [], "instructions": []},
                {
                    "id": "M",
                    "successors": [],
                    "phis": [
                        {"def": "x", "inputs": {"P": "a", "Q": "b"}},
                        {"def": "y", "inputs": {"P": "b", "Q": "a"}},
                    ],
                    "instructions": [
                        {"id": "use", "uses": ["x", "y"], "def": None, "call": False}
                    ],
                },
            ],
        },
        "spill_cost": {"a": 1, "b": 1, "x": 1, "y": 1},
        "edge_frequency": [
            {"pred": "E", "succ": "P", "frequency": 1},
            {"pred": "E", "succ": "Q", "frequency": 1},
            {"pred": "P", "succ": "M", "frequency": 1},
            {"pred": "Q", "succ": "M", "frequency": 3},
        ],
    }


class TransformContractTests(unittest.TestCase):
    def test_output_shape_and_public_values(self):
        # SPEC.md: "Output exactly {status,reason,live_in,live_out,interference,
        # call_forbidden,min_spill,copy_cost,locations,spills,edge_moves}."
        result = transform({"request": _public_request()}, {})
        expected_keys = {
            "status", "reason", "live_in", "live_out", "interference",
            "call_forbidden", "min_spill", "copy_cost", "locations",
            "spills", "edge_moves",
        }
        self.assertEqual(set(result.keys()), expected_keys)
        self.assertEqual(result["status"], "ALLOCATED")
        self.assertIsNone(result["reason"])
        self.assertEqual(result["min_spill"], 0)
        self.assertEqual(result["copy_cost"], 2)
        self.assertEqual(result["locations"]["a"], "reg:R0")
        self.assertEqual(result["locations"]["b"], "reg:R1")
        self.assertEqual(result["locations"]["x"], "reg:R1")
        self.assertEqual(result["locations"]["y"], "reg:R0")
        self.assertEqual(result["spills"], [])

    def test_caller_input_not_mutated(self):
        # SPEC.md: "leave caller inputs unchanged."
        request = _public_request()
        import copy
        snapshot = copy.deepcopy(request)
        transform({"request": request}, {})
        self.assertEqual(request, snapshot)

    def test_frequency_weighting_prefers_cold_edge_moves(self):
        # SPEC.md: "Reversing the two frequencies reverses the preferred
        # allocation." With P->M=3 and Q->M=1, x=R0,y=R1 is optimal.
        request = _public_request()
        for row in request["edge_frequency"]:
            if row["pred"] == "P" and row["succ"] == "M":
                row["frequency"] = 3
            elif row["pred"] == "Q" and row["succ"] == "M":
                row["frequency"] = 1
        result = transform({"request": request}, {})
        self.assertEqual(result["copy_cost"], 2)
        self.assertEqual(result["locations"]["x"], "reg:R0")
        self.assertEqual(result["locations"]["y"], "reg:R1")

    def test_single_register_spills_middle_of_path(self):
        # SPEC.md: "With one register and spill costs a:5,b:8,c:5, globally keep
        # a,c and spill b at cost8."
        request = {
            "config": {"registers": ["R0"], "call_clobbered": [], "precolors": {}},
            "cfg": {
                "entry": "B",
                "parameters": ["a", "b", "c"],
                "blocks": [
                    {
                        "id": "B",
                        "successors": [],
                        "phis": [],
                        "instructions": [
                            {"id": "d1", "uses": [], "def": "a", "call": False},
                            {"id": "d2", "uses": [], "def": "b", "call": False},
                            {"id": "u1", "uses": ["a"], "def": None, "call": False},
                            {"id": "d3", "uses": [], "def": "c", "call": False},
                            {"id": "u2", "uses": ["b"], "def": None, "call": False},
                            {"id": "u3", "uses": ["c"], "def": None, "call": False},
                        ],
                    }
                ],
            },
            "spill_cost": {"a": 5, "b": 8, "c": 5},
            "edge_frequency": [],
        }
        result = transform({"request": request}, {})
        self.assertEqual(result["min_spill"], 8)
        self.assertEqual(set(result["spills"]), {"b"})

    def test_precolor_call_clobber_precedence(self):
        # SPEC.md: "If any pinned register is call-forbidden, status is
        # UNSAT_PRECOLOR and reason PRECOLOR_CALL_CLOBBER."
        request = {
            "config": {
                "registers": ["R0"],
                "call_clobbered": ["R0"],
                "precolors": {"a": "R0"},
            },
            "cfg": {
                "entry": "B",
                "parameters": ["a"],
                "blocks": [
                    {
                        "id": "B",
                        "successors": [],
                        "phis": [],
                        "instructions": [
                            {"id": "call", "uses": ["a"], "def": None, "call": True}
                        ],
                    }
                ],
            },
            "spill_cost": {"a": 1},
            "edge_frequency": [],
        }
        result = transform({"request": request}, {})
        self.assertEqual(result["status"], "UNSAT_PRECOLOR")
        self.assertEqual(result["reason"], "PRECOLOR_CALL_CLOBBER")
        self.assertIsNone(result["min_spill"])
        self.assertIsNone(result["copy_cost"])
        self.assertEqual(result["locations"], {})
        self.assertEqual(result["spills"], [])
        self.assertEqual(result["edge_moves"], [])


if __name__ == "__main__":
    unittest.main()

